        node.property(Properties.MIN_VALUE, Signals.constant(min))
        node.property(Properties.MAX_VALUE, Signals.constant(max))
    }.registerChild()

fun Gauge(value: Signal<Float>, min: Float = 0f, max: Float = 1f): dev.pathland.view.core.View =
