     private static final class RecordingConnection implements PathlandConnection {
         private final List<byte[]> recorded = new CopyOnWriteArrayList<>();

         @Override
         public void send(byte[] bytes) {
             recorded.add(bytes);
         }

         @Override
         public boolean isOpen() {
