             List<String> values = new ArrayList<>();
             for (byte[] bytes : recorded) {
                 try {
                     ProtocolFrame frame = FrameCodec.decodeFrame(bytes);
                     for (Opcode op : frame.opcodes()) {
                         if (op.category() == 0x02 && op.command() == 0x03) { // PARAMETER::SET_TEXT
