-            String value = signal.get();
-            if (value == null) {
-                value = "";
-            }
-            if (!Objects.equals(lastWindowMetadata.get(field), value)) {
-                lastWindowMetadata.put(field, value);
-                sink.beginFrame();
-                sink.setWindowMetadata(field, value);
-                sink.endFrame();
