                "Circular signal dependency: computed '${describe()}' depends on itself",
            )
        }
        evaluateIfDirty()
        if (error != null) {
            rethrowError()
        }
        recordDependency()
        @Suppress("UNCHECKED_CAST")
        return cachedValue as T
    }

    fun evaluateIfDirty() {
        if (!dirty) return
        refreshProducers()
        dirty = false
        if (!firstRun && !depsChanged()) return
        firstRun = false
        ReactiveContext.push(this)
        resetProducers()
        try {
            val next = fn.get()
            if (equal.test(cachedValue, next)) {
                error = null
            } else {
                cachedValue = next
                error = null
                version++
                propagate()
            }
        } catch (t: Throwable) {
            if (error != t) {
                error = t
                version++
                propagate()
            }
        } finally {
            ReactiveContext.pop()
        }
    }
