        this.action = action;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = content.renderNode(env);
        Object existing = node.properties.get(Properties.EVENT_LISTENERS);
        int mask = existing instanceof Integer i ? i : 0;
        node.properties.put(
