         val created = frame.opcodes()
             .filter { it.category() == Categories.TREE && it.command() == Commands.Tree.CREATE_NODE }
             .map { it.b() and 0xffff }
         assertEquals(listOf(Components.VSTACK, Components.TEXT, Components.BUTTON, Components.TEXT), created)
